#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> t;   // t[i] = suma a[i - lowbit(i) + 1 .. i]

    Fenwick(int n) : n(n), t(n + 1, 0) {}

    void add(int i, long long v) {          // a[i] += v, 1 <= i <= n
        for (; i <= n; i += i & -i) t[i] += v;
    }
    long long sum(int i) const {            // a[1] + ... + a[i]
        long long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
    long long sum(int l, int r) const {     // a[l] + ... + a[r]
        return sum(r) - sum(l - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    Fenwick fw(n);
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        fw.add(i, x);
    }
    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {             // 1 i v: a[i] += v
            int i;
            long long v;
            cin >> i >> v;
            fw.add(i, v);
        } else {                     // 2 l r: suma a[l..r]
            int l, r;
            cin >> l >> r;
            cout << fw.sum(l, r) << '\n';
        }
    }
}

// k-ty element: najmniejsze i, dla którego sum(i) >= k (wszystkie a[i] >= 0). O(log n).
int kth(const vector<long long>& t, int n, long long k) {
    int pos = 0;
    int step = 1;
    while (step * 2 <= n) step *= 2;
    for (; step > 0; step /= 2) {
        if (pos + step <= n && t[pos + step] < k) {
            pos += step;
            k -= t[pos];
        }
    }
    return pos + 1;   // n + 1, jeśli suma wszystkich < k
}

