struct FenwickCount {
    int n;
    vector<int> t;
    FenwickCount(int n) : n(n), t(n + 1, 0) {}
    void add(int i, int v) { for (; i <= n; i += i & -i) t[i] += v; }
    int kth(int k) const {                 // k-ty najmniejszy wstawiony (1-indeksowany k)
        int pos = 0, step = 1;
        while (step * 2 <= n) step *= 2;
        for (; step > 0; step /= 2)
            if (pos + step <= n && t[pos + step] < k) {
                pos += step;
                k -= t[pos];
            }
        return pos + 1;
    }
};

vector<long long> buildFenwick(const vector<long long>& a) {   // a[1..n], a[0] nieużywane
    int n = a.size() - 1;
    vector<long long> t(a);
    t[0] = 0;
    for (int i = 1; i <= n; i++) {
        int parent = i + (i & -i);
        if (parent <= n) t[parent] += t[i];
    }
    return t;
}

struct FenwickXor {
    int n;
    vector<int> t;
    FenwickXor(int n) : n(n), t(n + 1, 0) {}
    void apply(int i, int v) { for (; i <= n; i += i & -i) t[i] ^= v; }   // a[i] ^= v
    int pref(int i) const { int s = 0; for (; i > 0; i -= i & -i) s ^= t[i]; return s; }
    int query(int l, int r) const { return pref(r) ^ pref(l - 1); }
};

