#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> t;
    Fenwick(int n) : n(n), t(n + 2, 0) {}
    void add(int i, long long v) { for (; i <= n; i += i & -i) t[i] += v; }
    long long sum(int i) const { long long s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
};

// Dodawanie na przedziale + suma na przedziale (1-indeksowane).
struct RangeFenwick {
    int n;
    Fenwick b1, b2;
    RangeFenwick(int n) : n(n), b1(n), b2(n) {}
    void rangeAdd(int l, int r, long long v) {
        b1.add(l, v);
        b1.add(r + 1, -v);          // dla r = n add jest no-op (i > n)
        b2.add(l, v * (l - 1));
        b2.add(r + 1, -v * r);
    }
    long long prefix(int i) const { return b1.sum(i) * i - b2.sum(i); }
    long long rangeSum(int l, int r) const { return prefix(r) - prefix(l - 1); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    RangeFenwick fw(n);
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        fw.rangeAdd(i, i, x);
    }
    while (q--) {
        int type, l, r;
        cin >> type >> l >> r;
        if (type == 1) {                // 1 l r v: dodaj v na [l, r]
            long long v;
            cin >> v;
            fw.rangeAdd(l, r, v);
        } else {                        // 2 l r: suma
            cout << fw.rangeSum(l, r) << '\n';
        }
    }
}

// Przedział-punkt: dodaj v na [l, r], odczytaj a[i].
struct RangeAddPointQuery {
    int n;
    vector<long long> t;
    RangeAddPointQuery(int n) : n(n), t(n + 2, 0) {}
    void add(int i, long long v) { for (; i <= n; i += i & -i) t[i] += v; }
    void rangeAdd(int l, int r, long long v) { add(l, v); add(r + 1, -v); }
    long long get(int i) const { long long s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
};

