#include <bits/stdc++.h>
using namespace std;

struct Fenwick2D {
    int n, m;
    vector<vector<long long>> t;
    Fenwick2D(int n, int m) : n(n), m(m), t(n + 1, vector<long long>(m + 1, 0)) {}

    void add(int x, int y, long long v) {          // a[x][y] += v, 1-indeksowane
        for (int i = x; i <= n; i += i & -i)
            for (int j = y; j <= m; j += j & -j) t[i][j] += v;
    }
    long long sum(int x, int y) const {            // suma a[1..x][1..y]
        long long s = 0;
        for (int i = x; i > 0; i -= i & -i)
            for (int j = y; j > 0; j -= j & -j) s += t[i][j];
        return s;
    }
    long long sum(int x1, int y1, int x2, int y2) const {   // prostokąt [x1..x2] x [y1..y2]
        return sum(x2, y2) - sum(x1 - 1, y2) - sum(x2, y1 - 1) + sum(x1 - 1, y1 - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q;
    cin >> n >> m >> q;
    Fenwick2D fw(n, m);
    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {                 // 1 x y v
            int x, y;
            long long v;
            cin >> x >> y >> v;
            fw.add(x, y, v);
        } else {                         // 2 x1 y1 x2 y2
            int x1, y1, x2, y2;
            cin >> x1 >> y1 >> x2 >> y2;
            cout << fw.sum(x1, y1, x2, y2) << '\n';
        }
    }
}

