struct Fenwick2DRange {
    int n, m;
    vector<vector<long long>> t;
    Fenwick2DRange(int n, int m) : n(n), m(m), t(n + 2, vector<long long>(m + 2, 0)) {}
    void add(int x, int y, long long v) {
        for (int i = x; i <= n; i += i & -i)
            for (int j = y; j <= m; j += j & -j) t[i][j] += v;
    }
    void rectAdd(int x1, int y1, int x2, int y2, long long v) {
