#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n;
    vector<long long> t;   // t[v] = suma przedziału węzła v; korzeń = 1, dzieci 2v i 2v+1

    SegTree(const vector<long long>& a) : n(a.size()), t(4 * a.size(), 0) { build(1, 0, n - 1, a); }

    void build(int v, int tl, int tr, const vector<long long>& a) {
        if (tl == tr) { t[v] = a[tl]; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a);
        build(2 * v + 1, tm + 1, tr, a);
        t[v] = t[2 * v] + t[2 * v + 1];
    }
    void update(int v, int tl, int tr, int pos, long long val) {   // a[pos] = val
        if (tl == tr) { t[v] = val; return; }
        int tm = (tl + tr) / 2;
        if (pos <= tm) update(2 * v, tl, tm, pos, val);
        else update(2 * v + 1, tm + 1, tr, pos, val);
        t[v] = t[2 * v] + t[2 * v + 1];
    }
    long long query(int v, int tl, int tr, int l, int r) const {   // suma a[l..r]
        if (r < tl || tr < l) return 0;                  // rozłączne
        if (l <= tl && tr <= r) return t[v];             // całkowicie w środku
        int tm = (tl + tr) / 2;
        return query(2 * v, tl, tm, l, r) + query(2 * v + 1, tm + 1, tr, l, r);
    }
    void update(int pos, long long val) { update(1, 0, n - 1, pos, val); }
    long long query(int l, int r) const { return query(1, 0, n - 1, l, r); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    SegTree st(a);
    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {            // 1 i v: a[i] = v (1-indeksowane)
            int i;
            long long v;
            cin >> i >> v;
            st.update(i - 1, v);
        } else {                    // 2 l r: suma a[l..r]
            int l, r;
            cin >> l >> r;
            cout << st.query(l - 1, r - 1) << '\n';
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

// Węzeł trzyma sumę i minimum naraz — łączenie dzieci w jednej funkcji.
struct Node {
    long long sum, mn;
};
Node combine(const Node& a, const Node& b) { return {a.sum + b.sum, min(a.mn, b.mn)}; }
const Node NEUTRAL = {0, LLONG_MAX};

struct SegTree {
    int n;
    vector<Node> t;
    SegTree(const vector<long long>& a) : n(a.size()), t(4 * a.size()) { build(1, 0, n - 1, a); }
    void build(int v, int tl, int tr, const vector<long long>& a) {
        if (tl == tr) { t[v] = {a[tl], a[tl]}; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a);
        build(2 * v + 1, tm + 1, tr, a);
        t[v] = combine(t[2 * v], t[2 * v + 1]);
    }
    void update(int v, int tl, int tr, int pos, long long val) {
        if (tl == tr) { t[v] = {val, val}; return; }
        int tm = (tl + tr) / 2;
        if (pos <= tm) update(2 * v, tl, tm, pos, val);
        else update(2 * v + 1, tm + 1, tr, pos, val);
        t[v] = combine(t[2 * v], t[2 * v + 1]);
    }
    Node query(int v, int tl, int tr, int l, int r) const {
        if (r < tl || tr < l) return NEUTRAL;
        if (l <= tl && tr <= r) return t[v];
        int tm = (tl + tr) / 2;
        return combine(query(2 * v, tl, tm, l, r), query(2 * v + 1, tm + 1, tr, l, r));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    SegTree st(a);
    while (q--) {
        int type, x, y;
        cin >> type >> x >> y;
        if (type == 1) st.update(1, 0, n - 1, x - 1, y);                  // a[x] = y
        else if (type == 2) cout << st.query(1, 0, n - 1, x - 1, y - 1).sum << '\n';
        else cout << st.query(1, 0, n - 1, x - 1, y - 1).mn << '\n';
    }
}

