struct SegMin {
    int n;
    vector<long long> t;
    SegMin(int n) : n(n), t(4 * n, LLONG_MAX) {}
    void update(int v, int tl, int tr, int pos, long long val) {
        if (tl == tr) { t[v] = val; return; }
        int tm = (tl + tr) / 2;
        if (pos <= tm) update(2 * v, tl, tm, pos, val);
        else update(2 * v + 1, tm + 1, tr, pos, val);
        t[v] = min(t[2 * v], t[2 * v + 1]);
    }
    long long query(int v, int tl, int tr, int l, int r) const {
        if (r < tl || tr < l) return LLONG_MAX;
        if (l <= tl && tr <= r) return t[v];
        int tm = (tl + tr) / 2;
        return min(query(2 * v, tl, tm, l, r), query(2 * v + 1, tm + 1, tr, l, r));
    }
    void update(int pos, long long val) { update(1, 0, n - 1, pos, val); }
    long long query(int l, int r) const { return query(1, 0, n - 1, l, r); }
};

using P = pair<long long, int>;   // (wartość, -indeks) -> przy remisie wygrywa mniejszy indeks
struct SegArgMax {
    int n;
    vector<P> t;
    SegArgMax(const vector<long long>& a) : n(a.size()), t(4 * a.size()) { build(1, 0, n - 1, a); }
    void build(int v, int tl, int tr, const vector<long long>& a) {
        if (tl == tr) { t[v] = {a[tl], -tl}; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a); build(2 * v + 1, tm + 1, tr, a);
        t[v] = max(t[2 * v], t[2 * v + 1]);
    }
    P query(int v, int tl, int tr, int l, int r) const {
        if (r < tl || tr < l) return {LLONG_MIN, 0};
        if (l <= tl && tr <= r) return t[v];
        int tm = (tl + tr) / 2;
        return max(query(2 * v, tl, tm, l, r), query(2 * v + 1, tm + 1, tr, l, r));
    }
    int argmax(int l, int r) const { return -query(1, 0, n - 1, l, r).second; }
};

struct SegMax {
    int n;
    vector<long long> t;
    SegMax(const vector<long long>& a) : n(a.size()), t(4 * a.size()) { build(1, 0, n - 1, a); }
    void build(int v, int tl, int tr, const vector<long long>& a) {
        if (tl == tr) { t[v] = a[tl]; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a); build(2 * v + 1, tm + 1, tr, a);
        t[v] = max(t[2 * v], t[2 * v + 1]);
    }
    // pierwszy indeks i >= l z a[i] >= x, albo -1
    int firstAtLeast(int v, int tl, int tr, int l, long long x) const {
        if (tr < l || t[v] < x) return -1;
        if (tl == tr) return tl;
        int tm = (tl + tr) / 2;
        int res = firstAtLeast(2 * v, tl, tm, l, x);
        if (res == -1) res = firstAtLeast(2 * v + 1, tm + 1, tr, l, x);
        return res;
    }
    int firstAtLeast(int l, long long x) const { return firstAtLeast(1, 0, n - 1, l, x); }
};

struct Info {
    long long sum, pref, suf, best;
};
Info makeLeaf(long long x) { return {x, x, x, x}; }
Info combine(const Info& L, const Info& R) {
    return {L.sum + R.sum,
            max(L.pref, L.sum + R.pref),
            max(R.suf, R.sum + L.suf),
            max({L.best, R.best, L.suf + R.pref})};
}

// Najcięższy ściśle rosnący podciąg: maksymalna suma wag w[i] po rosnących a[i].
long long heaviestIncreasing(const vector<int>& a, const vector<long long>& w) {
    vector<int> vals(a.begin(), a.end());
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = vals.size();
    vector<long long> t(2 * m, 0);   // iteracyjne drzewo maksimów
    auto update = [&](int p, long long v) {
        p += m;
        t[p] = max(t[p], v);
        for (; p > 1; p >>= 1) t[p >> 1] = max(t[p], t[p ^ 1]);
    };
    auto query = [&](int l, int r) {  // max na [l, r)
        long long res = 0;
        for (l += m, r += m; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res = max(res, t[l++]);
            if (r & 1) res = max(res, t[--r]);
        }
        return res;
    };
    long long best = 0;
    for (size_t i = 0; i < a.size(); i++) {
        int v = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();
        long long cur = query(0, v) + w[i];
        update(v, cur);
        best = max(best, cur);
    }
    return best;
}

