// Iteracyjne drzewo przedziałowe (bottom-up): liście w t[n..2n-1], korzeń t[1].
struct SegTreeIter {
    int n;
    vector<long long> t;
    SegTreeIter(const vector<long long>& a) : n(a.size()), t(2 * a.size()) {
        for (int i = 0; i < n; i++) t[n + i] = a[i];
        for (int i = n - 1; i > 0; i--) t[i] = t[2 * i] + t[2 * i + 1];
    }
    void update(int p, long long val) {        // a[p] = val, 0-indeksowane
        for (t[p += n] = val; p > 1; p >>= 1) t[p >> 1] = t[p] + t[p ^ 1];
    }
    long long query(int l, int r) const {      // suma na [l, r) — półotwarty!
        long long res = 0;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res += t[l++];
            if (r & 1) res += t[--r];
        }
        return res;
    }
};

