// Minimum na przedziale, bottom-up. Element neutralny = INF.
struct SegMinIter {
    int n;
    vector<int> t;
    SegMinIter(const vector<int>& a) : n(a.size()), t(2 * a.size(), INT_MAX) {
        for (int i = 0; i < n; i++) t[n + i] = a[i];
