#include <bits/stdc++.h>
using namespace std;

// Dodawanie na przedziale + suma i minimum na przedziale (lazy propagation), 0-indeksowane.
struct LazySegTree {
    int n;
    vector<long long> sum, mn, lazy;   // lazy[v] = dodatek do zepchnięcia do dzieci

    LazySegTree(const vector<long long>& a) : n(a.size()), sum(4 * n), mn(4 * n), lazy(4 * n, 0) {
        build(1, 0, n - 1, a);
    }
    void build(int v, int tl, int tr, const vector<long long>& a) {
        if (tl == tr) { sum[v] = mn[v] = a[tl]; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a);
        build(2 * v + 1, tm + 1, tr, a);
        pull(v);
    }
    void pull(int v) {
        sum[v] = sum[2 * v] + sum[2 * v + 1];
        mn[v] = min(mn[2 * v], mn[2 * v + 1]);
    }
    void apply(int v, int tl, int tr, long long add) {   // dodaj add do całego węzła
        sum[v] += add * (tr - tl + 1);
        mn[v] += add;
        lazy[v] += add;
    }
    void push(int v, int tl, int tr) {                   // zepchnij zaległy dodatek do dzieci
        if (lazy[v] != 0) {
            int tm = (tl + tr) / 2;
            apply(2 * v, tl, tm, lazy[v]);
            apply(2 * v + 1, tm + 1, tr, lazy[v]);
            lazy[v] = 0;
        }
    }
    void update(int v, int tl, int tr, int l, int r, long long add) {
        if (r < tl || tr < l) return;
        if (l <= tl && tr <= r) { apply(v, tl, tr, add); return; }
        push(v, tl, tr);
        int tm = (tl + tr) / 2;
        update(2 * v, tl, tm, l, r, add);
        update(2 * v + 1, tm + 1, tr, l, r, add);
        pull(v);
    }
    long long querySum(int v, int tl, int tr, int l, int r) {
        if (r < tl || tr < l) return 0;
        if (l <= tl && tr <= r) return sum[v];
        push(v, tl, tr);
        int tm = (tl + tr) / 2;
        return querySum(2 * v, tl, tm, l, r) + querySum(2 * v + 1, tm + 1, tr, l, r);
    }
    long long queryMin(int v, int tl, int tr, int l, int r) {
        if (r < tl || tr < l) return LLONG_MAX;
        if (l <= tl && tr <= r) return mn[v];
        push(v, tl, tr);
        int tm = (tl + tr) / 2;
        return min(queryMin(2 * v, tl, tm, l, r), queryMin(2 * v + 1, tm + 1, tr, l, r));
    }
    void update(int l, int r, long long add) { update(1, 0, n - 1, l, r, add); }
    long long querySum(int l, int r) { return querySum(1, 0, n - 1, l, r); }
    long long queryMin(int l, int r) { return queryMin(1, 0, n - 1, l, r); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    LazySegTree st(a);
    while (q--) {
        int type, l, r;
        cin >> type >> l >> r;
        l--, r--;                                   // na 0-indeksowanie
        if (type == 1) {                            // 1 l r v: dodaj v na [l, r]
            long long v;
            cin >> v;
            st.update(l, r, v);
        } else if (type == 2) {                     // 2 l r: suma
            cout << st.querySum(l, r) << '\n';
        } else {                                    // 3 l r: minimum
            cout << st.queryMin(l, r) << '\n';
        }
    }
}

