#include <bits/stdc++.h>
using namespace std;

// Dynamiczne drzewo przedziałowe na zakresie [lo, hi] (np. 0..1e9): węzły tworzone przy pierwszym użyciu.
struct DynamicSegTree {
    struct Node {
        long long sum = 0;
        int left = 0, right = 0;          // 0 = brak dziecka
    };
    vector<Node> t;
    long long lo, hi;

    DynamicSegTree(long long lo, long long hi, int reserveNodes = 0) : lo(lo), hi(hi) {
        t.reserve(reserveNodes + 2);
        t.push_back(Node());              // węzeł 0 = „pusty”
        t.push_back(Node());              // węzeł 1 = korzeń
    }
    int newNode() {
        t.push_back(Node());
        return (int)t.size() - 1;
    }
    void add(int v, long long tl, long long tr, long long pos, long long val) {
        t[v].sum += val;
        if (tl == tr) return;
        long long tm = tl + (tr - tl) / 2;          // bezpieczne także dla ujemnych
        if (pos <= tm) {
            if (t[v].left == 0) { int c = newNode(); t[v].left = c; }   // newNode może przenieść t!
            add(t[v].left, tl, tm, pos, val);
        } else {
            if (t[v].right == 0) { int c = newNode(); t[v].right = c; }
            add(t[v].right, tm + 1, tr, pos, val);
        }
    }
    long long query(int v, long long tl, long long tr, long long l, long long r) const {
        if (v == 0 || r < tl || tr < l) return 0;
        if (l <= tl && tr <= r) return t[v].sum;
        long long tm = tl + (tr - tl) / 2;
        return query(t[v].left, tl, tm, l, r) + query(t[v].right, tm + 1, tr, l, r);
    }
    void add(long long pos, long long val) { add(1, lo, hi, pos, val); }
    long long query(long long l, long long r) const { return query(1, lo, hi, l, r); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    DynamicSegTree st(0, 1000000000, q * 31);
    while (q--) {
        int type;
        long long x, y;
        cin >> type >> x >> y;
        if (type == 1) st.add(x, y);                   // 1 pos v: a[pos] += v
        else cout << st.query(x, y) << '\n';           // 2 l r: suma a[l..r]
    }
}

