    unordered_map<long long, long long> t;
    MapFenwick(long long n) : n(n) {}
    void add(long long i, long long v) { for (; i <= n; i += i & -i) t[i] += v; }
    long long sum(long long i) const {
        long long s = 0;
        for (; i > 0; i -= i & -i) {
            auto it = t.find(i);
            if (it != t.end()) s += it->second;
        }
        return s;
    }
};

