#include <bits/stdc++.h>
using namespace std;

// Trwałe drzewo przedziałowe licznikowe: wersja root[i] zawiera a[0..i-1] (wartości skompresowane do [0, m)).
struct PersistentSegTree {
    vector<int> leftChild, rightChild, cnt;   // węzeł 0 = puste drzewo (wskazuje sam na siebie)
    int m;

    PersistentSegTree(int m, int reserveNodes) : m(m) {
        leftChild.reserve(reserveNodes); rightChild.reserve(reserveNodes); cnt.reserve(reserveNodes);
        leftChild.push_back(0); rightChild.push_back(0); cnt.push_back(0);
    }
    int clone(int v) {
        leftChild.push_back(leftChild[v]);
        rightChild.push_back(rightChild[v]);
        cnt.push_back(cnt[v]);
        return (int)cnt.size() - 1;
    }
    int insert(int prev, int tl, int tr, int pos) {   // zwraca korzeń nowej wersji
        int cur = clone(prev);
        cnt[cur]++;
        if (tl == tr) return cur;
        int tm = (tl + tr) / 2;
        if (pos <= tm) { int c = insert(leftChild[prev], tl, tm, pos); leftChild[cur] = c; }
        else { int c = insert(rightChild[prev], tm + 1, tr, pos); rightChild[cur] = c; }
        return cur;
    }
    // k-ty najmniejszy (k od 1) w różnicy wersji hi - lo
    int kth(int hi, int lo, int tl, int tr, int k) const {
        if (tl == tr) return tl;
        int tm = (tl + tr) / 2;
        int inLeft = cnt[leftChild[hi]] - cnt[leftChild[lo]];
        if (k <= inLeft) return kth(leftChild[hi], leftChild[lo], tl, tm, k);
        return kth(rightChild[hi], rightChild[lo], tm + 1, tr, k - inLeft);
    }
    // ile wartości < pos w różnicy wersji hi - lo
    int countLess(int hi, int lo, int tl, int tr, int pos) const {
        if (pos <= tl || cnt[hi] - cnt[lo] == 0) return 0;
        if (tr < pos) return cnt[hi] - cnt[lo];
        int tm = (tl + tr) / 2;
        return countLess(leftChild[hi], leftChild[lo], tl, tm, pos) +
               countLess(rightChild[hi], rightChild[lo], tm + 1, tr, pos);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    vector<long long> vals(a);
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = vals.size();

    PersistentSegTree pst(m, 1 + n * (__lg(max(m, 1)) + 2));
    vector<int> root(n + 1, 0);              // root[0] = puste drzewo
    for (int i = 0; i < n; i++) {
        int pos = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();
        root[i + 1] = pst.insert(root[i], 0, m - 1, pos);
    }
    while (q--) {
        int l, r, k;                         // k-ty najmniejszy w a[l..r], 1-indeksowane
        cin >> l >> r >> k;
        int pos = pst.kth(root[r], root[l - 1], 0, m - 1, k);
        cout << vals[pos] << '\n';
    }
}

