#include <bits/stdc++.h>
using namespace std;

// Merge sort tree: węzeł trzyma posortowane elementy swojego przedziału.
struct MergeSortTree {
    int n;
    vector<vector<int>> t;

    MergeSortTree(const vector<int>& a) : n(a.size()), t(4 * a.size()) { build(1, 0, n - 1, a); }
    void build(int v, int tl, int tr, const vector<int>& a) {
        if (tl == tr) { t[v] = {a[tl]}; return; }
        int tm = (tl + tr) / 2;
        build(2 * v, tl, tm, a);
        build(2 * v + 1, tm + 1, tr, a);
        merge(t[2 * v].begin(), t[2 * v].end(), t[2 * v + 1].begin(), t[2 * v + 1].end(), back_inserter(t[v]));
    }
    // ile elementów a[l..r] jest < x
    int countLess(int v, int tl, int tr, int l, int r, int x) const {
        if (r < tl || tr < l) return 0;
        if (l <= tl && tr <= r) return lower_bound(t[v].begin(), t[v].end(), x) - t[v].begin();
        int tm = (tl + tr) / 2;
        return countLess(2 * v, tl, tm, l, r, x) + countLess(2 * v + 1, tm + 1, tr, l, r, x);
    }
    int countLess(int l, int r, int x) const { return countLess(1, 0, n - 1, l, r, x); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (auto& x : a) cin >> x;
    MergeSortTree mst(a);
    while (q--) {
        int l, r, x;                         // ile a[l..r] < x (1-indeksowane)
        cin >> l >> r >> x;
        cout << mst.countLess(l - 1, r - 1, x) << '\n';
    }
}

