// Offline: zapytania (l, r, x) — ile a[l..r] < x; 0-indeksowane.
vector<int> countLessOffline(const vector<int>& a, const vector<array<int, 3>>& qs) {
    int n = a.size();
    vector<int> order(n), qord(qs.size()), ans(qs.size()), bit(n + 1, 0);
    iota(order.begin(), order.end(), 0);
    iota(qord.begin(), qord.end(), 0);
    sort(order.begin(), order.end(), [&](int i, int j) { return a[i] < a[j]; });
    sort(qord.begin(), qord.end(), [&](int i, int j) { return qs[i][2] < qs[j][2]; });
    int p = 0;
    for (int qi : qord) {
        auto [l, r, x] = qs[qi];
        for (; p < n && a[order[p]] < x; p++)
            for (int i = order[p] + 1; i <= n; i += i & -i) bit[i]++;
        int s = 0;
        for (int i = r + 1; i > 0; i -= i & -i) s += bit[i];
        for (int i = l; i > 0; i -= i & -i) s -= bit[i];
        ans[qi] = s;
    }
    return ans;
}

