#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> t;
    Fenwick(int n) : n(n), t(n + 1, 0) {}
    void add(int i, long long v) { for (i++; i <= n; i += i & -i) t[i] += v; }   // i 0-indeksowane
    long long prefix(int i) const { long long s = 0; for (i++; i > 0; i -= i & -i) s += t[i]; return s; }  // [0, i]
    long long sum(int l, int r) const { return l > r ? 0 : prefix(r) - (l > 0 ? prefix(l - 1) : 0); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    vector<array<long long, 3>> ops(q);          // {typ, x, y}
    vector<long long> coords;
    for (auto& [type, x, y] : ops) {
        cin >> type >> x >> y;
        if (type == 1) coords.push_back(x);      // tylko punkty, które dostają wartości
    }
    sort(coords.begin(), coords.end());
    coords.erase(unique(coords.begin(), coords.end()), coords.end());
    int k = coords.size();
    Fenwick fw(max(k, 1));
    for (auto [type, x, y] : ops) {
        if (type == 1) {                         // 1 x v: punkt x dostaje +v
            int idx = lower_bound(coords.begin(), coords.end(), x) - coords.begin();
            fw.add(idx, y);
        } else {                                 // 2 L R: suma wartości punktów z x w [L, R]
            int l = lower_bound(coords.begin(), coords.end(), x) - coords.begin();
            int r = upper_bound(coords.begin(), coords.end(), y) - coords.begin() - 1;
            cout << fw.sum(l, r) << '\n';
        }
    }
}

