#include <bits/stdc++.h>
using namespace std;

// Li Chao tree: zbiór prostych y = k*x + b, zapytanie o minimum w punkcie x z [lo, hi].
struct LiChao {
    struct Line {
        long long k, b;
        long long eval(long long x) const { return k * x + b; }
    };
    struct Node {
        Line line;
        int left = -1, right = -1;
    };
    vector<Node> t;
    long long lo, hi;

    LiChao(long long lo, long long hi) : lo(lo), hi(hi) {}

    void addLine(long long k, long long b) {
        Line nw{k, b};
        if (t.empty()) { t.push_back({nw}); return; }
        int v = 0;
        long long l = lo, r = hi;
        while (true) {
            long long m = l + (r - l) / 2;
            bool betterLeft = nw.eval(l) < t[v].line.eval(l);
            bool betterMid = nw.eval(m) < t[v].line.eval(m);
            if (betterMid) swap(t[v].line, nw);          // w węźle zostaje lepsza w środku
            if (l == r) return;
            if (betterLeft != betterMid) {               // przecięcie w [l, m]
                if (t[v].left == -1) { t[v].left = t.size(); t.push_back({nw}); return; }
                v = t[v].left; r = m;
            } else {                                     // przecięcie w (m, r]
                if (t[v].right == -1) { t[v].right = t.size(); t.push_back({nw}); return; }
                v = t[v].right; l = m + 1;
            }
        }
    }
    long long query(long long x) const {                 // wymaga co najmniej jednej prostej
        long long res = LLONG_MAX;
        int v = 0;
        long long l = lo, r = hi;
        while (v != -1) {
            res = min(res, t[v].line.eval(x));
            long long m = l + (r - l) / 2;
            if (x <= m) { v = t[v].left; r = m; }
            else { v = t[v].right; l = m + 1; }
        }
        return res;
    }
    bool empty() const { return t.empty(); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    LiChao lc(-1000000, 1000000);              // zakres x z zapytań
    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {                       // 1 k b: dodaj prostą y = kx + b
            long long k, b;
            cin >> k >> b;
            lc.addLine(k, b);
        } else {                               // 2 x: minimum w punkcie x
            long long x;
            cin >> x;
            if (lc.empty()) cout << "BRAK\n";
            else cout << lc.query(x) << '\n';
        }
    }
}

