// dp[0] = 0, dp[i] = min_{j<i} (dp[j] + h[j] * h[i]) + c[i], 0 <= h[i] <= 10^6
int main() {
    int n;
    cin >> n;
    vector<long long> h(n), c(n), dp(n);
    for (auto& x : h) cin >> x;
    for (auto& x : c) cin >> x;
    LiChao lc(0, 1000000);
    dp[0] = 0;
    lc.addLine(h[0], dp[0]);                    // prosta stanu j: k = h[j], b = dp[j]
    for (int i = 1; i < n; i++) {
        dp[i] = lc.query(h[i]) + c[i];          // min po j < i w punkcie x = h[i]
        lc.addLine(h[i], dp[i]);
    }
    cout << dp[n - 1] << '\n';
}
